const KINDS = ['', 'SLOT_REGISTRATION', 'ISSUANCE_CANDIDATE', 'ISSUANCE_OUTCOME', 'KEY_PACKAGE',
  'SESSION_STATE', 'BINDING_PROFILE', 'REPLAY_RETENTION', 'COMMIT_RESULT', 'OUTPUT_ESCROW',
  'SELECTION_METADATA', 'RETAINED_PARENT', 'LOSING_CANDIDATE', 'MUTATION_HOLD', 'COMPONENT_SET',
  'ABSENCE_COMMITMENTS'];
const KIND_ID = Object.fromEntries(KINDS.slice(1).map((n, i) => [n, i + 1]));

const hex = (s) => new Uint8Array(Buffer.from(s, 'hex'));
const hx = (b) => Buffer.from(b).toString('hex');
const byId = (id) => VECTORS.find((v) => v.id === id);

async function rootKeys(v) {
  const namespaceKey = await deriveNamespaceKey({
    rootStorageKey: hex(v.rootStorageKeyHex),
    localContextId: hex(v.localContextIdHex),
    productProfileDigest: hex(v.profileDigestHex),
  });
  const manifestRootKey = await deriveManifestRootKey({
    namespaceKey, localContextId: hex(v.localContextIdHex), productProfileDigest: hex(v.profileDigestHex),
  });
  return { namespaceKey, manifestRootKey };
}

const selectorValue = (v) => decodePlaintext(M2_ROOT.SELECTOR_KIND, hex(v.selectorPlaintextHex));

function entriesFor(v) {
  return v.records
    .map((r) => ({ ...r, id: KIND_ID[r.kind] }))
    .filter((r) => r.id >= 1 && r.id <= 15)
    .sort((a, b) => (a.keyHex < b.keyHex ? -1 : a.keyHex > b.keyHex ? 1 : 0))
    .map((r) => manifestEntry({
      recordKey: hex(r.keyHex), recordKind: r.id, ciphertextDigest: hex(r.ciphertextDigestHex),
    }));
}

function holdOf(v) {
  const decoded = decodePlaintext(13, hex(v.holdPlaintextHex));
  if (decoded.presence === 0) return { presence: 0 };
  return {
    presence: 1,
    resultStatus: decoded.resultStatus,
    parentGeneration: decoded.parentGeneration,
    parentKeyedRoot: Uint8Array.prototype.slice.call(decoded.parentKeyedRoot),
  };
}

function facts(v, over = {}) {
  return {
    generation: BigInt(v.generation),
    manifestKey: hex(v.manifestKeyHex),
    manifestBytes: hex(v.manifestBytesHex),
    manifestCipherDigest: hex(v.manifestCipherDigestHex),
    keyedRoot: hex(v.keyedRootHex),
    mutationHold: holdOf(v),
    sessionBindingDigest: v.generationBindingDigestHex === null ? null : hex(v.generationBindingDigestHex),
    ...over,
  };
}

function concatBytes(parts) {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) { out.set(p, at); at += p.length; }
  return out;
}

// Re-encode a manifest whose declared entry count is trimmed, exactly as a historical manifest would.
function entryBytes(e) {
  return concatBytes([
    new Uint8Array([e.recordKey.length >> 8, e.recordKey.length & 0xff]),
    e.recordKey,
    new Uint8Array([e.recordKind >> 8, e.recordKind & 0xff]),
    new Uint8Array([e.recordKindVersion >> 8, e.recordKindVersion & 0xff]),
    e.ciphertextDigest,
  ]);
}

function trimmedManifest(v, dropKind) {
  const entries = entriesFor(v).filter((e) => e.recordKind !== dropKind);
  return concatBytes([
    Uint8Array.prototype.slice.call(hex(v.manifestBytesHex), 0, 10),
    new Uint8Array([0, 0, 0, entries.length]),
    ...entries.map(entryBytes),
  ]);
}

async function authorityFor(selectorVector, selectedVector, candidateVector) {
  const { manifestRootKey } = await rootKeys(selectorVector);
  return validateAuthority({
    selector: hex(selectorVector.selectorPlaintextHex),
    manifestRootKey,
    selected: facts(selectedVector),
    candidate: candidateVector === null ? null : facts(candidateVector),
  });
}

const codeOf = (fn) => { try { fn(); return 'NO_THROW'; } catch (e) { return e.code; } };
const awaitCode = async (thunk) => { try { await thunk(); return 'NO_THROW'; } catch (e) { return e.code; } };
const asyncCodeOf = async (fn) => { try { await fn(); return 'NO_THROW'; } catch (e) { return e.code; } };

describe('M2 keyed root and complete manifest — C-FMT known-answer vectors', () => {
  test('every vector carries fifteen data kinds exactly once', () => {
    for (const v of VECTORS) {
      expect(entriesFor(v)).toHaveLength(15);
      expect(new Set(entriesFor(v).map((e) => e.recordKind)).size).toBe(15);
    }
  });

  test('encodeManifest reproduces each literal vector manifest byte-for-byte', () => {
    for (const v of VECTORS) {
      expect(hx(encodeManifest(entriesFor(v)))).toBe(v.manifestBytesHex);
    }
  });

  test('decodeManifest round-trips each literal vector manifest', () => {
    for (const v of VECTORS) {
      const entries = decodeManifest(hex(v.manifestBytesHex));
      expect(entries).toHaveLength(15);
      expect(hx(encodeManifest(entries))).toBe(v.manifestBytesHex);
      expect(entries.map((e) => e.recordKind)).toEqual([...Array(15)].map((_, i) => i + 1));
    }
  });

  test('decodeManifest yields the exact keys, kind versions and ciphertext digests', () => {
    for (const v of VECTORS) {
      const entries = decodeManifest(hex(v.manifestBytesHex));
      const expected = entriesFor(v);
      expect(entries.map((e) => hx(e.recordKey))).toEqual(expected.map((e) => hx(e.recordKey)));
      expect(entries.map((e) => hx(e.ciphertextDigest))).toEqual(expected.map((e) => hx(e.ciphertextDigest)));
      expect(entries.map((e) => e.recordKindVersion)).toEqual(expected.map((e) => e.recordKindVersion));
      expect(entries[12].recordKindVersion).toBe(2);
    }
  });

  test('deriveNamespaceKey -> deriveManifestRootKey -> computeKeyedRoot reproduces each keyed root', async () => {
    for (const v of VECTORS) {
      const { manifestRootKey } = await rootKeys(v);
      const root = computeKeyedRoot({
        manifestRootKey,
        manifestKey: hex(v.manifestKeyHex),
        generation: BigInt(v.generation),
        manifestBytes: hex(v.manifestBytesHex),
      });
      expect(hx(root)).toBe(v.keyedRootHex);
    }
  });

  test('manifestKeyDigest matches the digest bound by the version-3 selector', () => {
    for (const v of VECTORS) {
      const sel = selectorValue(v);
      const bound = sel.generation === BigInt(v.generation) ? sel.manifestKeyDigest : sel.candidateManifestKeyDigest;
      expect(hx(manifestKeyDigest(hex(v.manifestKeyHex)))).toBe(hx(bound));
      expect(hx(manifestKeyDigest(hex(v.manifestKeyHex)))).toHaveLength(64);
    }
  });

  test('encodeManifestKey reproduces the kind-16 manifest key of each vector', () => {
    for (const v of VECTORS) {
      const key = hex(v.manifestKeyHex);
      const scope = key[10];
      const secureSessionIdentity = scope === 2 ? key.slice(43, 75) : null;
      const generationAt = scope === 2 ? 75 : 43;
      let value = 0n;
      for (const b of key.slice(generationAt, generationAt + 8)) value = (value << 8n) | BigInt(b);
      expect(hx(encodeManifestKey({
        scope, localContextId: hex(v.localContextIdHex), secureSessionIdentity, writeGeneration: value,
      }))).toBe(v.manifestKeyHex);
    }
  });

  test('ciphertextDigest reproduces every sealed data-record digest', () => {
    for (const v of VECTORS) {
      for (const r of v.records) {
        const id = KIND_ID[r.kind];
        if (id < 1 || id > 15) continue;
        const digest = ciphertextDigest({
          recordKey: hex(r.keyHex), recordKind: id,
          ciphertext: hex(r.ciphertextHex), tag: hex(r.tagHex),
        });
        expect(hx(digest)).toBe(r.ciphertextDigestHex);
      }
    }
  });

  test('the selector binds its published generation and the candidate tuple', () => {
    for (const v of VECTORS) {
      const sel = selectorValue(v);
      const selected = VECTORS.find((x) => BigInt(x.generation) === sel.generation);
      expect(sel.presence).toBe(1);
      expect(sel.generation).toBe(BigInt(selected.generation));
      expect(hx(sel.keyedRoot)).toBe(selected.keyedRootHex);
      expect(sel.candidateGeneration).toBe(BigInt(v.generation));
      expect(hx(sel.candidateKeyedRoot)).toBe(v.keyedRootHex);
    }
  });
});

describe('validateAuthority — published same-generation vectors', () => {
  test('EMPTY and ACTIVE selectors resolve to the selected generation with no candidate', async () => {
    for (const id of ['FMT-KAT-EMPTY', 'FMT-KAT-ACTIVE']) {
      const v = byId(id);
      const result = await authorityFor(v, v, null);
      expect(result.authority).toBe('SELECTED');
      expect(result.candidateIsAuthority).toBe(false);
      expect(result.selectedGeneration).toBe(BigInt(v.generation));
      expect(result.candidateGeneration).toBe(BigInt(v.generation));
      expect(hx(result.selectedKeyedRoot)).toBe(v.keyedRootHex);
      expect(result.candidateKeyedRoot).toBeNull();
      expect(result.state).toBe(selectorValue(v).state);
    }
  });

  test('the reconciliation vectors keep the old authority and never promote the candidate', async () => {
    const active = byId('FMT-KAT-ACTIVE');
    for (const [selectorId, candidateId] of [
      ['FMT-KAT-HOLD', 'FMT-KAT-HOLD'],
      ['FMT-KAT-EMPTY-HOLD', 'FMT-KAT-EMPTY-HOLD'],
    ]) {
      const sel = byId(selectorId);
      const cand = byId(candidateId);
      const selected = sel.id === 'FMT-KAT-HOLD' ? active : byId('FMT-KAT-EMPTY');
      const result = await authorityFor(sel, selected, cand);
      expect(result.authority).toBe('SELECTED');
      expect(result.candidateIsAuthority).toBe(false);
      expect(result.selectedGeneration).toBe(BigInt(selected.generation));
      expect(result.candidateGeneration).toBe(BigInt(cand.generation));
      expect(hx(result.selectedKeyedRoot)).toBe(selected.keyedRootHex);
      expect(hx(result.candidateKeyedRoot)).toBe(cand.keyedRootHex);
      expect(result.state).toBe(3);
    }
  });

  test('the EMPTY-origin hold has a pre-session selector and a SESSION-scoped candidate', async () => {
    const sel = byId('FMT-KAT-EMPTY-HOLD');
    const selected = byId('FMT-KAT-EMPTY');
    const result = await authorityFor(sel, selected, sel);
    expect(selected.generationBindingDigestHex).toBeNull();
    expect(sel.generationBindingDigestHex).not.toBeNull();
    expect(result.candidateIsAuthority).toBe(false);
  });

  test('a frozen result is returned and no input is mutated', async () => {
    const v = byId('FMT-KAT-ACTIVE');
    const selected = facts(v);
    const selector = hex(v.selectorPlaintextHex);
    const snapshot = { selector: hx(selector), manifestBytes: hx(selected.manifestBytes), key: hx(selected.manifestKey) };
    const { manifestRootKey } = await rootKeys(v);
    const result = validateAuthority({ selector, manifestRootKey, selected, candidate: null });
    expect(Object.isFrozen(result)).toBe(true);
    expect(result.selectedKeyedRoot).not.toBe(selected.keyedRoot);
    expect(hx(selector)).toBe(snapshot.selector);
    expect(hx(selected.manifestBytes)).toBe(snapshot.manifestBytes);
    expect(hx(selected.manifestKey)).toBe(snapshot.key);
    expect(Object.isFrozen(selected)).toBe(false);
  });
});

describe('the same-key historical subset can never satisfy the current root', () => {
  const v = byId('FMT-KAT-ACTIVE');

  test('a fourteen-entry same-key manifest is rejected as a historical subset', () => {
    for (const dropKind of [1, 7, 12, 15]) {
      expect(codeOf(() => decodeManifest(trimmedManifest(v, dropKind)))).toBe('HISTORICAL_SUBSET');
    }
  });

  test('a same-key subset can never be rooted under the current keyed root', async () => {
    const { manifestRootKey } = await rootKeys(v);
    for (const dropKind of [1, 7, 12, 15]) {
      expect(codeOf(() => computeKeyedRoot({
        manifestRootKey, manifestKey: hex(v.manifestKeyHex), generation: BigInt(v.generation),
        manifestBytes: trimmedManifest(v, dropKind),
      }))).toBe('HISTORICAL_SUBSET');
    }
  });

  test('validateAuthority rejects the same-key subset presented as the selected manifest', async () => {
    const { manifestRootKey } = await rootKeys(v);
    const bytes = trimmedManifest(v, 12);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(v.selectorPlaintextHex), manifestRootKey,
      selected: facts(v, { manifestBytes: bytes }), candidate: null,
    }))).toBe('HISTORICAL_SUBSET');
  });

  test('removing one key while duplicating another never yields a complete set', () => {
    const entries = entriesFor(v).map((e) => ({ ...e }));
    entries[10] = manifestEntry({
      recordKey: entries[11].recordKey.slice(), recordKind: 12, ciphertextDigest: entries[10].ciphertextDigest,
    });
    expect(codeOf(() => encodeManifest(entries))).toBe('UNSUPPORTED_VALUE');
  });

  test('an emptied manifest is never accepted as the current generation', () => {
    const empty = new Uint8Array(14);
    empty.set(new Uint8Array(Buffer.from('STYXMAN1', 'ascii')), 0);
    empty.set(new Uint8Array([0, 1]), 8);
    expect(codeOf(() => decodeManifest(empty))).toBe('HISTORICAL_SUBSET');
  });
});

describe('manifest structural rejections', () => {
  const v = byId('FMT-KAT-EMPTY');
  const bytes = () => hex(v.manifestBytesHex);

  test('wrong magic, unknown version and trailing bytes reject', () => {
    const bad = bytes(); bad[0] ^= 0xff;
    expect(codeOf(() => decodeManifest(bad))).toBe('MALFORMED_INPUT');
    const ver = bytes(); ver[9] = 2;
    expect(codeOf(() => decodeManifest(ver))).toBe('UNSUPPORTED_VALUE');
    expect(codeOf(() => decodeManifest(concatBytes([bytes(), new Uint8Array([0])]))))
      .toBe('MALFORMED_INPUT');
  });

  test('truncation and count inflation reject', () => {
    expect(codeOf(() => decodeManifest(bytes().slice(0, 40)))).toBe('MALFORMED_INPUT');
    const inflated = bytes();
    inflated[10] = 0; inflated[11] = 0; inflated[12] = 0; inflated[13] = 16;
    expect(codeOf(() => decodeManifest(inflated))).toBe('MANIFEST_INCOMPLETE');
  });

  test('a reordered entry pair rejects', () => {
    const entries = entriesFor(v).slice();
    const one = entries[3]; entries[3] = entries[4]; entries[4] = one;
    expect(codeOf(() => encodeManifest(entries))).toBe('MALFORMED_INPUT');
  });

  test('a duplicate kind with another kind removed rejects', () => {
    const entries = entriesFor(v).slice();
    entries[4] = manifestEntry({
      recordKey: entries[3].recordKey.slice(), recordKind: 4, ciphertextDigest: entries[4].ciphertextDigest,
    });
    expect(codeOf(() => encodeManifest(entries))).toBe('UNSUPPORTED_VALUE');
  });

  test('a non-data manifest entry kind rejects', () => {
    expect(codeOf(() => manifestEntry({
      recordKey: entriesFor(v)[0].recordKey, recordKind: 16, ciphertextDigest: new Uint8Array(32),
    }))).toBe('UNSUPPORTED_VALUE');
    expect(codeOf(() => manifestEntry({
      recordKey: entriesFor(v)[0].recordKey, recordKind: 0, ciphertextDigest: new Uint8Array(32),
    }))).toBe('UNSUPPORTED_VALUE');
  });

  test('a key whose kind does not match its record kind rejects', () => {
    const entries = entriesFor(v).slice();
    expect(codeOf(() => encodeManifest([
      entries[0], entries[1],
      { recordKey: entries[1].recordKey, recordKind: 3, recordKindVersion: 1, ciphertextDigest: entries[2].ciphertextDigest },
      ...entries.slice(3),
    ]))).toBe('CONTEXT_MISMATCH');
  });

  test('a non-canonical record key rejects', () => {
    const bad = entriesFor(v)[0].recordKey.slice(); bad[0] ^= 0xff;
    expect(codeOf(() => manifestEntry({ recordKey: bad, recordKind: 1, ciphertextDigest: new Uint8Array(32) })))
      .toBe('CONTEXT_MISMATCH');
  });

  test('a wrong entry kind version rejects', () => {
    const entries = entriesFor(v).slice();
    const wrong = [...entries];
    wrong[12] = { recordKey: entries[12].recordKey, recordKind: 13, recordKindVersion: 1, ciphertextDigest: entries[12].ciphertextDigest };
    expect(codeOf(() => encodeManifest(wrong))).toBe('UNSUPPORTED_VALUE');
  });
});

describe('keyed root field binding', () => {
  const v = byId('FMT-KAT-ACTIVE');

  test('a one-byte change in the literal manifest bytes changes the root', async () => {
    const { manifestRootKey } = await rootKeys(v);
    const base = hex(v.manifestBytesHex);
    const changed = base.slice(); changed[changed.length - 1] ^= 0x01;
    const expected = hx(computeKeyedRoot({
      manifestRootKey, manifestKey: hex(v.manifestKeyHex), generation: BigInt(v.generation), manifestBytes: base,
    }));
    const tampered = hx(computeKeyedRoot({
      manifestRootKey, manifestKey: hex(v.manifestKeyHex), generation: BigInt(v.generation), manifestBytes: changed,
    }));
    expect(expected).toBe(v.keyedRootHex);
    expect(tampered).not.toBe(v.keyedRootHex);
  });

  test('the root binds manifestKeyLength and the literal manifest key', async () => {
    const { manifestRootKey } = await rootKeys(v);
    const other = byId('FMT-KAT-EMPTY');
    // Re-rooting one generation's manifest under another generation's key is refused outright, so the
    // root can never be re-derived for a foreign key/generation pair.
    const code = codeOf(() => computeKeyedRoot({
      manifestRootKey, manifestKey: hex(other.manifestKeyHex),
      generation: BigInt(other.generation), manifestBytes: hex(v.manifestBytesHex),
    }));
    expect(['HISTORICAL_SUBSET', 'CONTEXT_MISMATCH']).toContain(code);
  });

  test('the root binds the generation and rejects generation zero', async () => {
    const { manifestRootKey } = await rootKeys(v);
    // Raising the generation no longer re-roots the same bytes: the entries belong to the manifest's
    // own generation, so the mismatch is rejected instead of producing a second root.
    expect(codeOf(() => computeKeyedRoot({
      manifestRootKey, manifestKey: hex(v.manifestKeyHex), generation: 3n, manifestBytes: hex(v.manifestBytesHex),
    }))).toBe('HISTORICAL_SUBSET');
    expect(codeOf(() => computeKeyedRoot({
      manifestRootKey, manifestKey: hex(v.manifestKeyHex), generation: 0n, manifestBytes: hex(v.manifestBytesHex),
    }))).toBe('MALFORMED_INPUT');
  });

  test('a kind-17 byte string is never accepted as a manifest key', async () => {
    const { manifestRootKey } = await rootKeys(v);
    expect(codeOf(() => computeKeyedRoot({
      manifestRootKey, manifestKey: hex(v.selectorPlaintextHex),
      generation: BigInt(v.generation), manifestBytes: hex(v.manifestBytesHex),
    }))).toBe('CONTEXT_MISMATCH');
    expect(codeOf(() => manifestKeyDigest(hex(v.selectorPlaintextHex)))).toBe('CONTEXT_MISMATCH');
  });

  test('a manifest key with a non-empty object id rejects', async () => {
    const { manifestRootKey } = await rootKeys(v);
    const key = hex(v.manifestKeyHex);
    const bogus = concatBytes([key, new Uint8Array([1])]);
    bogus[key.length - 1] = 1;
    expect(codeOf(() => computeKeyedRoot({
      manifestRootKey, manifestKey: bogus, generation: BigInt(v.generation), manifestBytes: hex(v.manifestBytesHex),
    }))).toBe('CONTEXT_MISMATCH');
  });
});

describe('cross-record authority rejections', () => {
  const v = byId('FMT-KAT-ACTIVE');

  async function run(over = {}) {
    const { manifestRootKey } = await rootKeys(v);
    return validateAuthority({
      selector: over.selector ?? hex(v.selectorPlaintextHex),
      manifestRootKey,
      selected: over.selected ?? facts(v),
      candidate: over.candidate ?? null,
    });
  }

  test('a selector keyed root that names another generation rejects', async () => {
    const other = byId('FMT-KAT-EMPTY');
    const sel = { ...selectorValue(v), keyedRoot: hex(other.keyedRootHex), candidateKeyedRoot: hex(other.keyedRootHex) };
    expect(await asyncCodeOf(() => run({ selector: encodePlaintext(17, sel) })))
      .toBe('ROOT_MISMATCH');
  });

  test('a selected manifest ciphertext digest that disagrees rejects', async () => {
    expect(await asyncCodeOf(() => run({ selected: facts(v, { manifestCipherDigest: new Uint8Array(32) }) })))
      .toBe('ROOT_MISMATCH');
  });

  test('a selected generation that disagrees with the selector rejects', async () => {
    const empty = byId('FMT-KAT-EMPTY');
    expect(await asyncCodeOf(() => run({ selected: facts(v, { generation: 1n, manifestKey: hex(empty.manifestKeyHex) }) })))
      .toBe('CONTEXT_MISMATCH');
  });

  test('a selected manifest key that does not match the selector digest rejects', async () => {
    const empty = byId('FMT-KAT-EMPTY');
    expect(await asyncCodeOf(() => run({ selected: facts(v, { manifestKey: hex(empty.manifestKeyHex) }) })))
      .toBe('CONTEXT_MISMATCH');
  });

  test('a separate candidate declared by a same-generation selector rejects', async () => {
    expect(await asyncCodeOf(() => run({ candidate: facts(byId('FMT-KAT-HOLD')) })))
      .toBe('CANDIDATE_MISMATCH');
  });

  test('a candidate-naming selector without a candidate rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')), candidate: null,
    }))).toBe('CANDIDATE_MISMATCH');
  });

  test('a present selected hold alongside a candidate rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    const selected = facts(byId('FMT-KAT-ACTIVE'), { mutationHold: holdOf(hold) });
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey, selected, candidate: facts(hold),
    }))).toBe('CANDIDATE_MISMATCH');
  });

  test('a tombstoned candidate hold rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { mutationHold: { presence: 0 } }),
    }))).toBe('CANDIDATE_MISMATCH');
  });

  test('a candidate generation that disagrees with the selector rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const empty = byId('FMT-KAT-EMPTY');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { generation: 4n, manifestKey: hex(empty.manifestKeyHex) }),
    }))).toBe('CONTEXT_MISMATCH');
  });

  test('a candidate manifest key that does not match the selector digest rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { manifestKey: hex(byId('FMT-KAT-EMPTY').manifestKeyHex) }),
    }))).toBe('CONTEXT_MISMATCH');
  });

  test('a candidate manifest ciphertext digest that disagrees rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { manifestCipherDigest: new Uint8Array(32) }),
    }))).toBe('CANDIDATE_MISMATCH');
  });

  test('a candidate keyed root that disagrees rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { keyedRoot: hex(byId('FMT-KAT-ACTIVE').keyedRootHex) }),
    }))).toBe('CANDIDATE_MISMATCH');
  });

  test('a candidate carrying the same-key subset rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    const bytes = trimmedManifest(hold, 12);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { manifestBytes: bytes }),
    }))).toBe('HISTORICAL_SUBSET');
  });

  test('an INDETERMINATE candidate hold with the wrong parent root rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    const bad = { ...holdOf(hold), parentKeyedRoot: hex(byId('FMT-KAT-EMPTY').keyedRootHex) };
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { mutationHold: bad }),
    }))).toBe('PARENT_MISMATCH');
  });

  test('an INDETERMINATE candidate hold with the wrong parent generation rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    const bad = { ...holdOf(hold), parentGeneration: 7n };
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { mutationHold: bad }),
    }))).toBe('PARENT_MISMATCH');
  });

  test('a terminal candidate hold does not compare its parent to a moved selector', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    const terminal = { ...holdOf(hold), resultStatus: 1, parentGeneration: 7n, parentKeyedRoot: new Uint8Array(32) };
    const result = await validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { mutationHold: terminal }),
    });
    expect(result.candidateIsAuthority).toBe(false);
  });

  test('a candidate bound to another session profile rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { sessionBindingDigest: new Uint8Array(32).fill(9) }),
    }))).toBe('CANDIDATE_MISMATCH');
  });

  test('a session binding digest that disagrees with the key scope rejects', async () => {
    const hold = byId('FMT-KAT-HOLD');
    const { manifestRootKey } = await rootKeys(hold);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(hold.selectorPlaintextHex), manifestRootKey,
      selected: facts(byId('FMT-KAT-ACTIVE')),
      candidate: facts(hold, { sessionBindingDigest: null }),
    }))).toBe('CONTEXT_MISMATCH');
    const empty = byId('FMT-KAT-EMPTY');
    const { manifestRootKey: emptyRoot } = await rootKeys(empty);
    expect(await asyncCodeOf(() => validateAuthority({
      selector: hex(empty.selectorPlaintextHex), manifestRootKey: emptyRoot,
      selected: facts(empty, { sessionBindingDigest: new Uint8Array(32).fill(3) }), candidate: null,
    }))).toBe('CONTEXT_MISMATCH');
  });

  test('a noncanonical selector plaintext rejects', async () => {
    const { manifestRootKey } = await rootKeys(v);
    const bad = hex(v.selectorPlaintextHex); bad[5] ^= 0xff;
    expect(await asyncCodeOf(() => validateAuthority({ selector: bad, manifestRootKey, selected: facts(v), candidate: null })))
      .toBe('UNSUPPORTED_VALUE');
  });
});

describe('module shape', () => {
  test('errors carry a stable code and the frozen registry', () => {
    const err = new M2RootError('MALFORMED_INPUT', 'x');
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe('M2RootError');
    expect(err.code).toBe('MALFORMED_INPUT');
    expect(Object.isFrozen(M2_ROOT)).toBe(true);
    expect(M2_ROOT.MANIFEST_KIND).toBe(16);
    expect(M2_ROOT.SELECTOR_KIND).toBe(17);
  });

  test('the codec error type stays distinct from the root error type', () => {
    expect(codeOf(() => decodeManifest(new Uint8Array(0)))).toBe('MALFORMED_INPUT');
    let seen = null;
    try { decodePlaintext(17, new Uint8Array(3)); } catch (e) { seen = e; }
    expect(seen).toBeInstanceOf(M2StorageCodecError);
  });

  test('the awaitCode helper is exercised', async () => {
    expect(await awaitCode(() => { throw new M2RootError('X', 'y'); })).toBe('X');
    expect(await awaitCode(() => null)).toBe('NO_THROW');
  });
});

describe('M2 complete manifest — deterministic property tests', () => {
  // Every permutation of a valid manifest must be rejected: adjacent transpositions, the reverse and
  // every rotation cover a strictly ascending order violation for each possible position.
  test('any permutation of a valid manifest is rejected', () => {
    const v = byId('FMT-KAT-ACTIVE');
    const entries = entriesFor(v);
    const permutations = [];
    for (let i = 1; i < entries.length; i += 1) {
      const swapped = entries.slice();
      [swapped[i - 1], swapped[i]] = [swapped[i], swapped[i - 1]];
      permutations.push(swapped);
    }
    permutations.push(entries.slice().reverse());
    for (let r = 1; r < entries.length; r += 1) permutations.push(entries.slice(r).concat(entries.slice(0, r)));
    for (const permutation of permutations) {
      expect(codeOf(() => encodeManifest(permutation))).not.toBe('NO_THROW');
      // The same permuted order, laid out as raw bytes, must also be rejected by the decoder.
      const raw = concatBytes([
        Uint8Array.prototype.slice.call(hex(v.manifestBytesHex), 0, 10),
        new Uint8Array([0, 0, 0, permutation.length]),
        ...permutation.map(entryBytes),
      ]);
      expect(codeOf(() => decodeManifest(raw))).not.toBe('NO_THROW');
    }
  });

  // Any single-byte mutation of the manifest bytes either fails structurally or changes the root.
  test('any single-byte mutation of the manifest bytes changes the recomputed keyed root', async () => {
    const v = byId('FMT-KAT-ACTIVE');
    const { manifestRootKey } = await rootKeys(v);
    const base = hex(v.manifestBytesHex);
    const root = hex(v.keyedRootHex);
    let structural = 0;
    let rooted = 0;
    for (let offset = 0; offset < base.length; offset += 1) {
      const mutated = Uint8Array.prototype.slice.call(base);
      mutated[offset] ^= 0x01;
      let recomputed = null;
      try {
        recomputed = computeKeyedRoot({
          manifestRootKey, manifestKey: hex(v.manifestKeyHex), generation: BigInt(v.generation), manifestBytes: mutated,
        });
      } catch (e) {
        structural += 1;
        continue;
      }
      expect(hx(recomputed)).not.toBe(root);
      rooted += 1;
    }
    expect(structural + rooted).toBe(base.length);
    expect(structural).toBeGreaterThan(0);
    expect(rooted).toBeGreaterThan(0);
  });

  // A manifest built from the current records never equals a subset manifest, and no subset manifest
  // can be rooted under the current manifest key.
  test('a current manifest never equals a subset manifest under the same root', async () => {
    const v = byId('FMT-KAT-ACTIVE');
    const { manifestRootKey } = await rootKeys(v);
    const current = hex(v.manifestBytesHex);
    for (const drop of [15, 1, 8]) {
      const subset = trimmedManifest(v, drop);
      expect(hx(subset)).not.toBe(v.manifestBytesHex);
      expect(codeOf(() => computeKeyedRoot({
        manifestRootKey, manifestKey: hex(v.manifestKeyHex), generation: BigInt(v.generation), manifestBytes: subset,
      }))).toBe('HISTORICAL_SUBSET');
    }
    expect(hx(current)).toBe(v.manifestBytesHex);
  });
});

// Targeted regressions for the defects the named reviewers confirmed at the review head.
describe('reviewer-confirmed defects — targeted regressions', () => {
  const v = byId('FMT-KAT-ACTIVE');

  async function run(over = {}) {
    const { manifestRootKey } = await rootKeys(v);
    return validateAuthority({
      selector: over.selector ?? hex(v.selectorPlaintextHex),
      manifestRootKey,
      selected: over.selected ?? facts(v),
      candidate: over.candidate ?? null,
    });
  }

  test('a present hold carrying further kind-13 fields is read, not rejected', async () => {
    const hold = {
      presence: 1,
      resultStatus: 2,
      parentGeneration: BigInt(v.generation),
      parentKeyedRoot: hex(v.keyedRootHex),
      operationIdentity: new Uint8Array(32).fill(0x5a),
    };
    const result = await run({ selected: facts(v, { mutationHold: hold }) });
    expect(result.authority).toBe('SELECTED');
  });

  test('a hold resultStatus outside the closed commit-outcome set fails closed', async () => {
    for (const resultStatus of [0, 4, 200]) {
      const hold = {
        presence: 1,
        resultStatus,
        parentGeneration: BigInt(v.generation),
        parentKeyedRoot: hex(v.keyedRootHex),
      };
      expect(await asyncCodeOf(() => run({ selected: facts(v, { mutationHold: hold }) })))
        .toBe('UNSUPPORTED_VALUE');
    }
  });

  test('a non-object hold reports M2RootError and never a raw TypeError', async () => {
    for (const mutationHold of [undefined, 7, 'x', Symbol('h')]) {
      const code = await asyncCodeOf(() => run({ selected: facts(v, { mutationHold }) }));
      expect(code).toBe('MALFORMED_INPUT');
    }
  });

  test('the selected unresolved hold must name the selector authority', async () => {
    const wrong = await asyncCodeOf(() => run({
      selected: facts(v, {
        mutationHold: { presence: 1, resultStatus: 3, parentGeneration: 99n, parentKeyedRoot: new Uint8Array(32).fill(0xee) },
      }),
    }));
    expect(wrong).toBe('PARENT_MISMATCH');
    const right = await run({
      selected: facts(v, {
        mutationHold: { presence: 1, resultStatus: 3, parentGeneration: BigInt(v.generation), parentKeyedRoot: hex(v.keyedRootHex) },
      }),
    });
    expect(right.authority).toBe('SELECTED');
  });

  test('a manifest entry keyed to another generation is not a complete generation', async () => {
    const other = byId('FMT-KAT-EMPTY');
    const entries = entriesFor(v).map((e, i) => (i === 0
      ? manifestEntry({
        recordKey: hex(entriesFor(other)[0].recordKey),
        recordKind: 1,
        ciphertextDigest: e.ciphertextDigest,
      })
      : e));
    const { manifestRootKey } = await rootKeys(v);
    expect(codeOf(() => computeKeyedRoot({
      manifestRootKey,
      manifestKey: hex(v.manifestKeyHex),
      generation: BigInt(v.generation),
      manifestBytes: encodeManifest(entries),
    }))).toMatch(/HISTORICAL_SUBSET|CONTEXT_MISMATCH/);
  });
});
